import React from "react";
import { Helmet } from "react-helmet";
import NavbarLocal from "../components/navbar";
import ConsumableCard from "../components/consumableCard";
import Separator from "../components/separator";
try {
    var BEER_SUMMARY_JSON = require('../assets/beer/summary.json');
} catch (e) {
    BEER_SUMMARY_JSON = { fileMap: [] };
}

const filterItems = (summaryJson, POST_SOURCE) => {
    return summaryJson && summaryJson.fileMap && Object.keys(summaryJson.fileMap)
        .filter((file) => file.indexOf(POST_SOURCE) === 0)
        .map((file) => summaryJson.fileMap[file])
        .map((item) => ({
        ...item,
        name: item.name || "Unnamed",
        img: item.img || "default-image",
        }))
        .sort((a, b) => a.name.localeCompare(b.name));
};

export default () => {
    const beers = filterItems(BEER_SUMMARY_JSON, 'src/assets/beer');
    const handleBeerClick = (beerName, currentCount) => {
      console.log(`Clicked on ${beerName}, current count is: ${currentCount + 1}`);
    };

    /*const snacks = filterItems(SNACK_SUMMARY_JSON, 'src/assets/snack');
    const handleSnackClick = (snackName, currentCount) => {
      console.log(`Clicked on ${snackName}, current count is: ${currentCount + 1}`);
    };*/
    
    return (
        <>
        <Helmet>
            <title>CISTEM - Order</title>
        </Helmet>
        <NavbarLocal />

        
        <Separator title={'Bières'} />
        <ConsumableCard
        items={beers}
        onCardClick={handleBeerClick}
        getImagePath={(item) => require(`../assets/beer/img/${item.img}.png`)}
        />
        <Separator title={'Softs'} />
        <ConsumableCard
        items={beers}
        onCardClick={handleBeerClick}
        getImagePath={(item) => require(`../assets/beer/img/${item.img}.png`)}
        />
        <Separator title={'Nourriture'} />
        <ConsumableCard
        items={beers}
        onCardClick={handleBeerClick}
        getImagePath={(item) => require(`../assets/beer/img/${item.img}.png`)}
        />
        </>
    )
};

