import React, { useState } from "react";
import '../assets/css/style.scss';
import { H3 } from './titles';
import { Card, CardBody, CardTitle } from "reactstrap";

const ConsumableCard = ({ items, onCardClick, getImagePath }) => {
  const [counts, setCounts] = useState({});

  const handleClick = (itemName) => {
    setCounts((prevCounts) => ({
      ...prevCounts,
      [itemName]: (prevCounts[itemName] || 0) + 1,
    }));
    if (onCardClick) {
      onCardClick(itemName, counts[itemName] || 0);
    }
  };

  return (
    <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-around" }}>
      {items.map((item) => {
        const count = counts[item.name] || 0;
        return (
          <div key={item.name || "unknown"} style={{ flex: "0 0 20%", margin: "20px", maxWidth: "40%" }}>
            <Card
              onClick={() => handleClick(item.name)}
              color="light"
              outline
              style={{ cursor: "pointer", position: "relative" }}
            >
              <CardBody>
                <CardTitle className="text-center">
                  <H3>{item.name || "Unnamed"}</H3>
                </CardTitle>
              </CardBody>
              <img
                alt={item.name || "No name"}
                src={getImagePath ? getImagePath(item) : ""}
                style={{
                  width: "200px",
                  position: "relative",
                  marginTop: "5px",
                }}
                className="container-fluid justify-content-center"
              />
              <div
                className="bubble"
                style={{
                  position: "absolute",
                  bottom: "10px",
                  right: "10px",
                  backgroundColor: "#007bff",
                  color: "#fff",
                  borderRadius: "50%",
                  width: "50px",
                  height: "50px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  fontSize: "14px",
                  fontWeight: "bold",
                  boxShadow: "0 2px 5px rgba(0, 0, 0, 0.3)",
                }}
              >
                {count === 0 ? "+" : count}
              </div>
            </Card>
          </div>
        );
      })}
    </div>
  );
};

export default ConsumableCard;
