import React, { useState } from "react";
import {
    Modal,
    ModalContent,
    ModalHeader,
    ModalBody,
    ModalFooter,
    Button,
} from "@heroui/react";
import { Autocomplete, AutocompleteItem } from "@nextui-org/react";
import { useNavigate } from "react-router-dom";
import { useFilter } from "@react-aria/i18n";

export const ModalNavigate = ({ isOpen, onClose, title, list, schedule }) => {
    const navigate = useNavigate();
    const [value, setValue] = useState("");

    const handleSelection = (selected) => {
      setValue(selected);
    };

    const onAction = () => {
        navigate(`/schedule/${schedule}/${encodeURIComponent(list[value].label)}`);
    }

    const [fieldState, setFieldState] = useState({
        selectedKey: "",
        inputValue: "",
        items: list,
      });
    
      const { startsWith } = useFilter({ sensitivity: "base" });
    
      const onSelectionChange = (key) => {
        setFieldState((prevState) => {
          const selectedItem = prevState.items.find((option) => option.key === key);
        setValue(key);
          return {
            inputValue: selectedItem?.label || "",
            selectedKey: key,
            items: list.filter((item) => startsWith(item.label, selectedItem?.label || "")),
          };
        });
      };

    return (
        <Modal isOpen={isOpen} onOpenChange={onClose}>
            <ModalContent>
                <>
                    <ModalHeader className="flex flex-col gap-1">{title}</ModalHeader>
                    <ModalBody>
                            <Autocomplete
                                className="max-w-xs"
                                inputValue={fieldState.inputValue}
                                items={fieldState.items}
                                label="Écrit ou fait défiler"
                                placeholder="Search a value"
                                selectedKey={fieldState.selectedKey}
                                variant="bordered"
                                onSelectionChange={onSelectionChange}
                            >
                                {(item) => <AutocompleteItem key={item.key}>{item.label}</AutocompleteItem>}
                            </Autocomplete>
                    </ModalBody>
                    <ModalFooter>
                        <Button color="danger" variant="light" onPress={onClose}>
                            Close
                        </Button>
                        <Button color="primary" onPress={onAction} isDisabled={value ? false: true}>
                            Go to Schedule
                        </Button>
                    </ModalFooter>
                </>
            </ModalContent>
        </Modal>
    );
};