import React from "react";
import moment from "moment";
import { Table, TableBody, TableCell, TableColumn, TableHeader, TableRow } from "@nextui-org/react";
import { LocalUser } from "./user";
import { Col, Row } from "reactstrap";

const Cell = ({ children, color, size }) => {
    return (
        <span
            style={{
                backgroundColor: color,
                height: "50px",
                display: "flex",
                color: "#000",
                fontSize: "0.75rem",
                borderRadius: "0.75rem",
            }}
        >
            <span style={{
                display:'flex',
                justifyContent: "center",
                text: "center",
                verticalAlign: "middle",
                whiteSpace: 'nowrap',
                padding: '0.85rem',
              }}
            >
              {children}
            </span>
        </span>
    );
};


export const Debug = ({ data }) => {
  return (
    <div>
      {Object.keys(data).map((person) => (
        <div key={person}>
          {Object.keys(data[person]['schedule']).map((date) => (
            <div key={date}>
              {data[person]['schedule'][date]['perms'].length === 0 ? (
                <p>empty</p>
              ) : (
                data[person]['schedule'][date]['perms'].map((perm, permIndex) => (
                  <div>
                    <p>Length : {data[person]['schedule'][date]['perms'].length}</p>
                    <p>Person: {data[person]['user']}</p>
                    <p>Date: {data[person]['schedule'][date]['day']}</p>
                    <p>Perm: {perm['title']}</p>
                    <p>Perm: {perm['start'].toString()}</p>
                    <p>Perm: {perm['end'].toString()}</p>
                  </div>
                ))
              )}
            </div>
          ))}
        </div>
      ))}
    </div>
  );
};

export const GlobalTimetable = ({ data, dates, entities, left_title }) => {
  return (
      <div style={{ overflowX: 'auto', width: '100%' }}>
          <Table aria-label="Timetable">
              <TableHeader>
                  <TableColumn>{left_title}</TableColumn>
                  {Object.keys(dates).map((day, index) => (
                      <TableColumn key={index}>{moment(dates[day]).format('dddd D MMM')}</TableColumn>
                  ))}
              </TableHeader>
              <TableBody>
                  {Object.keys(data).map((person, personIndex) => (
                      <TableRow key={personIndex}>
                          <TableCell><LocalUser name={data[person]['user']} /></TableCell>
                          {Object.keys(dates).map((day, dayIndex) => (
                              <TableCell key={dayIndex}>
                                  {data[person]['schedule'].find(d => d.day === moment(dates[day]).toString())?.perms.length > 0 ? (
                                      <Row>
                                          {data[person]['schedule'].find(d => d.day === moment(dates[day]).toString()).perms.map((perm, permIndex) => {
                                              const durationInHours = moment(perm['end']).diff(moment(perm['start']), 'hours');
                                              return (
                                                  <Col key={permIndex} className="g-0">
                                                      <Cell
                                                          color={entities[perm['title']] || "#ccc"}
                                                          size={durationInHours}
                                                      >
                                                          <span>{moment(perm['start']).format('HH')}h - {moment(perm['end']).format('HH')}h | {perm['title']}</span>
                                                      </Cell>
                                                  </Col>
                                              );
                                          })}
                                      </Row>
                                  ) : null}
                              </TableCell>
                          ))}
                      </TableRow>
                  ))}
              </TableBody>
          </Table>
      </div>
  );
};

export const PersonalTimetable = ({ data, dates, entities, left_title }) => {
  const entities_ = ["Montage", ...Object.keys(entities), "Démontage"];
  return (
    <div style={{ overflowX: 'auto', width: '100%' }}>
      <Table aria-label="Timetable">
          <TableHeader>
              <TableColumn>{left_title}</TableColumn>
              {Object.keys(dates).map((day, index) => (
                  <TableColumn key={index}>{moment(dates[day]).format('dddd D MMM')}</TableColumn>
              ))}
          </TableHeader>
          <TableBody>
                  {entities_.filter(point => 
                        data.some(dayData => 
                            dayData.perms.some(perm => perm.title === point)
                        )
                    ).map((point, pointIndex) => (
                  <TableRow key={pointIndex}>
                      <TableCell><LocalUser name={point} img="/assets/fosdem_ci_purple.png"/></TableCell>
                      {Object.keys(dates).map((day, dayIndex) => (
                                <TableCell key={dayIndex}><Row>
                                    {data[dayIndex] && data[dayIndex]['perms'].length > 0 ? (
                                        data[dayIndex]['perms'].map((perm, permIndex) => (
                                            perm['title'] !== point ? (
                                                null
                                            ) : (
                                                <Col className="g-0"><Cell
                                                    key={permIndex}
                                                    color={entities[perm['title']] || "#ccc"}
                                                >
                                                    <span>{moment(perm['start']).format('HH')}h - {moment(perm['end']).format('HH')}h</span>
                                                </Cell></Col>
                                            )
                                        ))
                                    ) : null}
                                </Row></TableCell>
                            ))}
                  </TableRow>
              ))}
          </TableBody>
      </Table>
    </div>
  );
};

export const BarTimetable = ({ data, dates, entities, left_title }) => {
  const { VENDREDI, LUNDI, ...filtered } = dates
    return (
        <div style={{ overflowX: 'auto', width: '100%' }}>
            <Table aria-label="Timetable">
                <TableHeader>
                    <TableColumn>{left_title}</TableColumn>
                    {Object.keys(filtered).map((day, index) => (
                        <TableColumn key={index}>{moment(filtered[day]).format('dddd D MMM')}</TableColumn>
                    ))}
                </TableHeader>
                <TableBody>
                    {Object.keys(data).map((person, personIndex) => (
                        <TableRow key={personIndex}>
                            <TableCell><LocalUser name={data[person].name} /></TableCell>
                            {Object.keys(filtered).map((day, dayIndex) => (
                                <TableCell key={dayIndex}>
                                    {data[person].perms[moment(filtered[day])] ? (
                                        <Row>
                                            {data[person].perms[moment(filtered[day])].map((perm, permIndex) => {
                                                const durationInHours = moment(perm['end']).diff(moment(perm['start']), 'hours');
                                                return (
                                                    <Col key={permIndex} className="g-0">
                                                        <Cell
                                                            color={entities[perm['title']] || " #a569bd "}
                                                            size={durationInHours}
                                                        >
                                                            <span>{moment(perm['start']).format('HH')}h - {moment(perm['end']).format('HH')}h</span>
                                                        </Cell>
                                                    </Col>
                                                );
                                            })}
                                        </Row>
                                    ) : null}
                                </TableCell>
                            ))}
                        </TableRow>
                    ))}
                </TableBody>
            </Table>
        </div>
    );
};